def transform(grid):
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    ph, pw = r1-r0+1, c1-c0+1

    # Find another location containing the same surrounding pattern, and
    # copy its contents into the masked rectangle.
    best = None
    best_score = -1
    best_valid = -1
    for sr in range(h-ph+1):
        for sc in range(w-pw+1):
            if sr == r0 and sc == c0:
                continue
            score = valid = 0
            for dr in range(ph):
                for dc in range(pw):
                    v = grid[sr+dr][sc+dc]
                    if v != 8:
                        valid += 1
                        if grid[r0+dr][c0+dc] == 8:
                            continue
                        if v == grid[r0+dr][c0+dc]:
                            score += 1
            for r in range(h):
                for c in range(w):
                    if r0 <= r < r0+ph and c0 <= c < c0+pw:
                        continue
                    dr, dc = r-r0, c-c0
                    rr, cc = sr+dr, sc+dc
                    if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 8:
                        valid += 1
                        if grid[r][c] == grid[rr][cc]:
                            score += 1
            # Prefer candidates whose surrounding rows/columns match well.
            if score > best_score or (score == best_score and valid > best_valid):
                best_score, best_valid = score, valid
                best = (sr, sc)

    sr, sc = best
    return [[grid[sr+dr][sc+dc] for dc in range(pw)] for dr in range(ph)]
